module TopModule (
    output zero
);

    assign zero = 1'b0;

endmodule

module TopModule (
    input  [31:0] in,
    output [31:0] out
);

    // Byte-reversal permutation: maps byte i to byte (3-i)
    // Byte 0 (bits 7:0)  -> Byte 3 (bits 31:24)
    // Byte 1 (bits 15:8) -> Byte 2 (bits 23:16)
    // Byte 2 (bits 23:16) -> Byte 1 (bits 15:8)
    // Byte 3 (bits 31:24) -> Byte 0 (bits 7:0)

    assign out = {in[7:0], in[15:8], in[23:16], in[31:24]};

endmodule

module TopModule (
    input  a,
    input  b,
    output out
);

    assign out = a & b;

endmodule

module TopModule (
    input  clk,
    input  reset,
    output [9:0] q
);

    // Internal register to hold the counter value
    reg [9:0] counter;

    // Synchronous reset and count logic
    always @(posedge clk) begin
        if (reset) begin
            counter <= 10'd0;
        end else begin
            if (counter == 10'd999) begin
                counter <= 10'd0;
            end else begin
                counter <= counter + 10'd1;
            end
        end
    end

    // Continuous assignment to drive the output port
    assign q = counter;

endmodule

module TopModule (
    input  [2:0] a,
    input  [2:0] b,
    output [2:0] out_or_bitwise,
    output       out_or_logical,
    output [5:0] out_not
);

    // Bitwise OR of the two 3-bit vectors
    assign out_or_bitwise = a | b;

    // Logical OR: reduces to a single bit (true if any bit is 1)
    assign out_or_logical = |(a | b);

    // Inverse of both vectors:
    // Upper half (bits [5:3]) = ~b
    // Lower half (bits [2:0]) = ~a
    assign out_not = {~b, ~a};

endmodule

module TopModule (
    input  [7:0] a,
    input  [7:0] b,
    input  [7:0] c,
    input  [7:0] d,
    output [7:0] min
);

    // Internal signals to hold intermediate minimum values
    wire [7:0] min_ab;
    wire [7:0] min_cd;
    wire [7:0] min_final;

    // Step 1: Find minimum of 'a' and 'b'
    assign min_ab = (a < b) ? a : b;

    // Step 2: Find minimum of 'c' and 'd'
    assign min_cd = (c < d) ? c : d;

    // Step 3: Find minimum of the two intermediate results
    assign min_final = (min_ab < min_cd) ? min_ab : min_cd;

    // Output the final minimum value
    assign min = min_final;

endmodule

module TopModule (
    input  p1a,
    input  p1b,
    input  p1c,
    input  p1d,
    input  p2a,
    input  p2b,
    input  p2c,
    input  p2d,
    output p1y,
    output p2y
);

    // 7420: Two 4-input NAND gates
    // Each gate outputs the NAND of its four inputs
    assign p1y = ~(p1a & p1b & p1c & p1d);
    assign p2y = ~(p2a & p2b & p2c & p2d);

endmodule

module TopModule (
    input  clk,
    input  d,
    output q
);

    // Internal register to hold the value sampled on the negative edge
    reg q_neg;

    // Always block triggered on the positive edge of the clock
    always @(posedge clk) begin
        q_neg <= d;      // Store 'd' in the internal register
    end

    // Always block triggered on the negative edge of the clock
    always @(negedge clk) begin
        q_neg <= d;      // Store 'd' in the internal register
    end

    // Continuous assignment to drive the output q
    // q follows q_neg, updating on either clock edge
    assign q = q_neg;

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  load,
    input  ena,
    input  [3:0] data,
    output reg [3:0] q
);

    always @(posedge clk or posedge areset) begin
        if (areset)
            q <= 4'b0000;
        else if (load)
            q <= data;
        else if (ena)
            q <= {1'b0, q[3:1]};
        else
            q <= q;
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  in,
    output out
);

    // State encoding: 2'b00 = B, 2'b01 = A
    reg [1:0] state, next_state;

    // State register (synchronous reset, active-high)
    always @(posedge clk) begin
        if (reset)
            state <= 2'b00;  // B
        else
            state <= next_state;
    end

    // Next-state logic (Moore machine)
    always @(*) begin
        case (state)
            2'b00: begin // State B, out = 1
                if (in)
                    next_state = 2'b00; // B --in=1--> B
                else
                    next_state = 2'b01; // B --in=0--> A
            end
            2'b01: begin // State A, out = 0
                if (in)
                    next_state = 2'b01; // A --in=1--> A
                else
                    next_state = 2'b00; // A --in=0--> B
            end
            default: next_state = 2'b00;
        endcase
    end

    // Output logic (Moore: output depends only on state)
    assign out = (state == 2'b00) ? 1'b1 : 1'b0;

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  j,
    input  k,
    output out
);

    // State encoding: 2 bits for two states
    typedef enum logic [1:0] {
        OFF = 2'b00,
        ON  = 2'b01
    } state_t;

    state_t state, next_state;

    // Next-state logic (Moore machine)
    always_comb begin
        case (state)
            OFF: begin
                if (j == 1'b1)
                    next_state = ON;
                else
                    next_state = OFF;
            end
            ON: begin
                if (k == 1'b1)
                    next_state = OFF;
                else
                    next_state = ON;
            end
            default: next_state = OFF; // Should never happen
        endcase
    end

    // State register with asynchronous active-high reset
    always_ff @(posedge clk or posedge areset) begin
        if (areset)
            state <= OFF;
        else
            state <= next_state;
    end

    // Output logic (Moore: output depends only on state)
    assign out = (state == ON) ? 1'b1 : 1'b0;

endmodule
